<script>
  export let data;
  const filters = [['all', 'All records'], ['issuance', 'Issuance'], ['transfers', 'Transfers'], ['market', 'Collector Market'], ['verification', 'Verification']];
  const label = (kind) => ({ created: 'Edition created', published: 'Edition published', issued: 'Copy issued', acquired: 'Primary acquisition completed', transferred: 'Ownership transferred', gifted: 'Copy gifted', inherited: 'Copy inherited', donated: 'Copy donated', listing_opened: 'Resale listing opened', offer_accepted: 'Offer accepted', verified: 'Authenticity verified', royalty_paid: 'Artist royalty paid', corrected: 'Record corrected' }[kind] || String(kind).replaceAll('_', ' '));
  const copy = (event) => event.releases?.edition_size ? `Copy ${String(event.edition_number ?? 1).padStart(2, '0')}/${event.releases.edition_size}` : 'Open Edition';
</script>
<svelte:head><title>Provenance Records — Noizes Exchange</title></svelte:head>
<main><p class="eyebrow">Noizes Exchange</p><h1>Provenance Records</h1><p class="lede">The living history of authenticated music editions.</p><nav><a href="/exchange">Discover</a><a href="/exchange/collector-market">Collector Market</a><a class="active" href="/exchange/provenance">Provenance Records</a></nav><div class="filters">{#each filters as [value, name]}<a class:chosen={data.filter === value} href={`/exchange/provenance?filter=${value}`}>{name}</a>{/each}</div>{#if data.error}<p class="notice">{data.error}</p>{/if}<section aria-label="Provenance events">{#each data.events as event}<a class="event" href={event.acquisition_id ? `/exchange/copy/${event.acquisition_id}` : '#'}><div class="line"><span>↗</span></div><div class="event-copy"><p class="artist">{event.releases?.artist_name || 'Noizes Registry'}</p><h2>{event.releases?.title || 'Authenticated edition'} <small>· {copy(event)}</small></h2><p>{label(event.kind)}</p><footer><span>◈ Signature recorded</span><span>{new Date(event.occurred_at).toLocaleString('en-KE', { dateStyle: 'medium', timeStyle: 'short' })}</span></footer></div><b>→</b></a>{/each}{#if !data.events.length}<p class="empty">No provenance records match this filter.</p>{/if}</section></main>
<style>main{max-width:1050px;margin:auto;padding:36px clamp(18px,4vw,56px) 80px}.eyebrow,.artist{color:#a57aff;text-transform:uppercase;letter-spacing:.14em;font-size:.7rem;font-weight:800;margin:0 0 8px}h1{font-size:clamp(3.1rem,6vw,5.7rem);line-height:.88;letter-spacing:-.065em;color:#fff;margin:0}.lede{color:#c7c1d4;font-size:1.15rem;margin:15px 0 22px}nav{display:flex;border:1px solid #302e40;border-radius:999px;overflow:auto;width:fit-content;max-width:100%;background:#0e0d13}nav a{padding:11px 23px;white-space:nowrap;color:#bdb7ca;text-decoration:none;font-weight:700}nav .active{background:#7043f7;color:#fff}.filters{display:flex;gap:8px;overflow:auto;margin:28px 0 20px}.filters a{white-space:nowrap;border:1px solid #3c374b;border-radius:999px;padding:8px 13px;color:#d5cfdf;text-decoration:none;font-size:.82rem}.filters .chosen{background:#fff;color:#111;border-color:#fff}section{border-top:1px solid #312d3d}.event{display:grid;grid-template-columns:52px 1fr 28px;gap:15px;text-decoration:none;color:#f4f1fa;border-bottom:1px solid #312d3d;padding:18px 0}.line{border-right:1px solid #a97835;display:flex;align-items:start;justify-content:center}.line span{height:32px;width:32px;border-radius:50%;border:1px solid #e3ad48;color:#ffd071;display:grid;place-items:center;background:#18130d}.event h2{margin:0;font-size:1.15rem}.event h2 small{color:#bab2c9;font-size:.83rem;font-weight:500}.event-copy>p:not(.artist){margin:6px 0 14px;color:#d0cadb}.event footer{display:flex;gap:20px;flex-wrap:wrap;color:#a9a1b8;font-size:.78rem}.event footer span:first-child{color:#6de6cc}.event>b{align-self:center;color:#c4a1ff;font-size:1.3rem}.notice,.empty{padding:18px;border:1px solid #4a3a36;color:#ffd99d;border-radius:9px}@media(max-width:520px){main{padding:24px 15px}.event{grid-template-columns:35px 1fr 18px;gap:10px}.line span{width:25px;height:25px}.event footer{display:block}.event footer span{display:block;margin-top:5px}.event h2{font-size:1rem}}</style>
